{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "pod_failure",
      "evidence": [
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name AS pod, metric, count(*) AS n, max(value) AS max_value FROM normal_metrics WHERE attr_k8s_pod_name LIKE 'geo%' AND metric = 'k8s.container.restarts' GROUP BY 1,2 UNION ALL SELECT attr_k8s_pod_name, metric, count(*), max(value) FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'geo%' AND metric = 'k8s.container.restarts' GROUP BY 1,2", "claim": "The geo pod's restart counter rose from 0 in normal to 2–6 during the abnormal window, showing repeated crash-restarts."},
        {"kind": "metric", "sql": "SELECT metric, count(*) AS n, avg(value) AS avg_value, max(value) AS max_value FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'geo%' AND metric IN ('k8s.container.ready','k8s.pod.phase') GROUP BY 1", "claim": "The geo container reports ready=0 for every abnormal sample, so it never became available again."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n, avg(duration)/1e6 AS avg_ms FROM abnormal_traces WHERE service_name = 'geo' OR (service_name = 'search' AND span_name = 'geo.Geo/Nearby') GROUP BY 1,2,3,4", "claim": "geo emits no spans in the abnormal window, while search's geo.Geo/Nearby client calls all return Error in about 0.02 ms."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) AS n FROM normal_traces WHERE service_name = 'search' AND span_name = 'geo.Geo/Nearby' GROUP BY 1,2 UNION ALL SELECT span_name, attr_status_code, count(*) FROM abnormal_traces WHERE service_name = 'search' AND span_name = 'geo.Geo/Nearby' GROUP BY 1,2", "claim": "In normal traffic search's geo calls all succeed; in the abnormal window every one of them errors."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'search' AND span_name IN ('geo.Geo/Nearby','search.Search/Nearby') GROUP BY 1,2,3", "claim": "Search's own Nearby handler returns Error on every request that depends on geo; 447 of 447 errored."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) AS n FROM abnormal_logs WHERE service_name = 'search' AND level = 'ERROR' GROUP BY 1,2,3", "claim": "Search logs 'Failed to get nearby hotels from geo service' about 1595 times in the abnormal window."}
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'frontend' AND span_name IN ('search.Search/Nearby','HTTP /hotels') GROUP BY 1,2,3,4,5", "claim": "Frontend's search.Search/Nearby client calls and HTTP /hotels server spans all error, and /hotels returns 500 for 461 requests."},
        {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces WHERE service_name = 'frontend' AND attr_span_kind = 'Server' GROUP BY 1,2 ORDER BY 1,2", "claim": "Other frontend routes (/recommendations, /restaurants, /museums, /cinema, /user) still return 200, so the impact is limited to /hotels."}
      ]
    }
  ]
}
